  push!(__eqs, connect(gdc.y, q_err.u2))
  push!(__eqs, connect(gq.y, deq.u1))
  push!(__eqs, connect(q_err.y, deq.u2))
  push!(__eqs, connect(COSTHE, nzdiv.u1))
  push!(__eqs, connect(csum.y, nzdiv.u2))
  push!(__eqs, connect(nzdiv.y, coordnz.u))
  push!(__eqs, connect(NZ, nz_err.u1))
  push!(__eqs, connect(coordnz.y, nz_err.u2))
  push!(__eqs, connect(nz_err.y, g1843.u))
  push!(__eqs, connect(VTOTALI, vsum.u1))
  push!(__eqs, connect(veps.y, vsum.u2))
  push!(__eqs, connect(g1843.y, gamdot.u1))
  push!(__eqs, connect(vsum.y, gamdot.u2))
  push!(__eqs, connect(gamdot.y, g_fb.u1))
  push!(__eqs, connect(int_gamdotf.y, g_fb.u2))
  push!(__eqs, connect(g_fb.y, g_rate.u))
  push!(__eqs, connect(g_rate.y, int_gamdotf.u))
  push!(__eqs, connect(gamdot.y, gfil.u1))
  push!(__eqs, connect(int_gamdotf.y, gfil.u2))
  push!(__eqs, connect(gq.y, degc_p.u1))
  push!(__eqs, connect(gfil.y, degc_p.u2))
  push!(__eqs, connect(degc_p.y, degc.u))
  push!(__eqs, connect(DLEDEG, t_fb.u1))
  push!(__eqs, connect(int_detrim.y, t_fb.u2))
  push!(__eqs, connect(t_fb.y, t_rate.u))
  push!(__eqs, connect(t_rate.y, int_detrim.u))
  push!(__eqs, connect(deq.y, decmd.u1))
  push!(__eqs, connect(degc.y, decmd.u2))
  push!(__eqs, connect(int_detrim.y, decmd.u3))
  push!(__eqs, connect(decmd.y, DECMD))

  # Return completely constructed System
  return System(__eqs, ModelingToolkit.t_nounits, __vars, __params; systems=__systems, initial_conditions=__initial_conditions, guesses=__guesses, name, initialization_eqs=__initialization_eqs, bindings=__bindings, assertions=__assertions)
end
